#!/usr/bin/env bash
# Generates a local .env with strong random secrets and an RS256 key pair for JWT signing.
# Safe to re-run: existing files are kept unless --force is given. Secrets are never printed.
set -euo pipefail
cd "$(dirname "$0")/.."

FORCE=false
[[ "${1:-}" == "--force" ]] && FORCE=true

rand() { openssl rand -hex "${1:-24}"; }

if [[ -f .env && "$FORCE" == false ]]; then
  echo ".env already exists — keeping it (use --force to regenerate; this invalidates existing database passwords)."
else
  umask 077
  cat > .env <<ENV
# Generated by scripts/init-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Do not commit.
POSTGRES_ADMIN_USER=grandvista_admin
POSTGRES_ADMIN_PASSWORD=$(rand)
AUTH_DB_PASSWORD=$(rand)
ROOM_DB_PASSWORD=$(rand)
BOOKING_DB_PASSWORD=$(rand)
PAYMENT_DB_PASSWORD=$(rand)
POSTGRES_HOST_PORT=5433
EUREKA_USERNAME=eureka
EUREKA_PASSWORD=$(rand)
BOOKING_SERVICE_CLIENT_SECRET=$(rand 32)
PAYMENT_SERVICE_CLIENT_SECRET=$(rand 32)
PAYMENT_WEBHOOK_SECRET=$(rand 32)
GV_BOOTSTRAP_ADMIN_EMAIL=admin@grandvista.local
GV_BOOTSTRAP_ADMIN_PASSWORD=$(rand 12)
GV_HOTEL_ZONE=Asia/Kolkata
GV_DEMO_SEED_ENABLED=true
GV_HOLD_TTL=15m
API_DOCS_ENABLED=true
GV_COOKIE_SECURE=true
GV_CORS_ALLOWED_ORIGINS=http://localhost:3000,http://localhost:5173
GATEWAY_HOST_PORT=8080
FRONTEND_HOST_PORT=3000
ENV
  echo "Wrote .env (permissions 600). The bootstrap administrator password is stored there as GV_BOOTSTRAP_ADMIN_PASSWORD."
fi

SECRETS=infrastructure/secrets
mkdir -p "$SECRETS"
chmod 700 "$SECRETS"
if [[ -f "$SECRETS/jwt-private.pem" && "$FORCE" == false ]]; then
  echo "JWT key pair already exists — keeping it."
else
  openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out "$SECRETS/jwt-private.pem" 2>/dev/null
  openssl pkey -in "$SECRETS/jwt-private.pem" -pubout -out "$SECRETS/jwt-public.pem"
  # Readable by the container's non-root user; the 700 directory keeps other host users out.
  chmod 644 "$SECRETS/jwt-private.pem" "$SECRETS/jwt-public.pem"
  echo "Generated RS256 key pair in $SECRETS/ (git-ignored)."
fi
